{
  "name": "@omagents/omagents",
  "version": "0.15.0",
  "description": "Opencode agent toolkit: bundled skills, MCP servers, parallel execution, and superpowers",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "omagents": "bin/install.js"
  },
  "keywords": [
    "opencode",
    "plugin",
    "skills",
    "mcp",
    "agents"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/omagents/omagents"
  },
  "dependencies": {
    "@omagents/core": "0.15.0"
  }
}

#!/usr/bin/env node
/**
 * OmAgents OpenCode installer.
 *
 * Run via: npx @omagents/omagents
 *
 * Adds "@omagents/omagents" to the plugin array in opencode.json.
 * Checks both global (~/.config/opencode/opencode.json) and project-level configs.
 */

import fs from "fs"
import path from "path"
import os from "os"

const USAGE = "Usage: npx @omagents/omagents [options]"

function findOpencodeConfig() {
  const candidates = [
    path.join(process.cwd(), "opencode.json"),
    path.join(process.cwd(), "opencode.jsonc"),
    path.join(os.homedir(), ".config", "opencode", "opencode.json"),
    path.join(os.homedir(), ".config", "opencode", "opencode.jsonc"),
  ]

  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate
  }

  // Default to a project-level config when no existing config is found.
  return path.join(process.cwd(), "opencode.json")
}

export async function setupOpencode() {
  const configPath = findOpencodeConfig()
  const configDir = path.dirname(configPath)

  // Read existing config or start fresh
  let config = {}
  if (fs.existsSync(configPath)) {
    const raw = fs.readFileSync(configPath, "utf-8")
    try {
      config = JSON.parse(raw)
    } catch {
      // JSONC: strip line comments only outside strings (simplified:
      // strip lines that start with optional whitespace + //)
      const stripped = raw
        .split("\n")
        .map((line) => {
          const trimmed = line.trimStart()
          if (trimmed.startsWith("//")) return ""
          return line
        })
        .join("\n")
      config = JSON.parse(stripped)
    }
  }

  // OpenCode V2 renamed the config key "plugin" -> "plugins". V2 still
  // normalizes the V1 key, so writing "plugin" works on both — but when the
  // file already uses the native V2 key, add there instead of mixing styles.
  const pluginKey = Array.isArray(config.plugins)
    ? "plugins"
    : Array.isArray(config.plugin)
      ? "plugin"
      : "plugin"

  // Ensure plugin array exists
  config[pluginKey] = config[pluginKey] || []

  // Check if already installed (either key)
  const pkgName = "@omagents/omagents"
  const isOmagents = (p) =>
    p === pkgName ||
    (typeof p === "string" && p.startsWith(pkgName + "@")) ||
    (p && typeof p === "object" && typeof p.package === "string" && p.package.startsWith(pkgName))
  const alreadyInstalled = config.plugin?.some(isOmagents) || config.plugins?.some(isOmagents)

  if (alreadyInstalled) {
    console.log(`[omagents] Already in ${configPath}`)
    console.log("[omagents] Restart OpenCode to activate.")
    return
  }

  // Add to plugin array
  config[pluginKey].push(pkgName)

  // Write config
  fs.mkdirSync(configDir, { recursive: true })
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + "\n", "utf-8")

  console.log(`[omagents] Added "${pkgName}" to ${configPath}`)
  console.log("[omagents] Restart OpenCode to activate.")
}

function printHelp() {
  console.log(`${USAGE}

Install OmAgents for OpenCode without a positional host argument.

Options:
  --help     Show this help message
  --version  Show the package version`)
}

async function main(args) {
  if (args.length === 0) {
    await setupOpencode()
    return
  }

  if (args.length === 1 && args[0] === "--help") {
    printHelp()
    return
  }

  if (args.length === 1 && args[0] === "--version") {
    const pkg = JSON.parse(fs.readFileSync(new URL("../package.json", import.meta.url), "utf8"))
    console.log(pkg.version)
    return
  }

  console.error(`[omagents] Unknown or unexpected arguments: ${args.join(" ")}`)
  console.error(USAGE)
  process.exitCode = 1
}

main(process.argv.slice(2)).catch((err) => {
  console.error("[omagents]", err.message)
  process.exitCode = 1
})

/**
 * OmAgents plugin for OpenCode.ai
 *
 * Auto-registers bundled skills, MCP servers, parallel execution, and
 * superpowers (imported as a dependency) so users can install with a
 * single line in opencode.json.
 */

import path from "path"
import fs from "fs"
import { fileURLToPath, pathToFileURL } from "url"
import { createParallelHooks, setupParallelV2 } from "./parallel.js"
import {
  AGENT_VENV_BIN,
  ensureBaseEnvironment,
  getCorePaths,
  listSkillDefinitions,
  renderSkillForHost,
  resolveMcpServers,
  SUPERPOWERS_DOCS_PATH_PREFERENCE,
} from "@omagents/core"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const OMAGENTS_DIR = path.resolve(__dirname, "../../..")
const CORE_PATHS = getCorePaths()
const SKILLS_DIR = CORE_PATHS.skillsDir

// Directories containing skill helper scripts to expose on PATH
const SKILL_SCRIPT_DIRS = [
  path.join(SKILLS_DIR, "deep-research", "scripts"),
  path.join(SKILLS_DIR, "markitdown-converter", "scripts"),
  path.join(SKILLS_DIR, "playwright-web-scraping", "scripts"),
  path.join(SKILLS_DIR, "_shared", "scripts"),
]

// Built-in MCP servers bundled by this plugin. Core resolves the canonical
// catalog; OpenCode V1 serialization adds `enabled` at this adapter boundary.
const BUILTIN_MCPS = {}
for (const [name, def] of Object.entries(resolveMcpServers())) {
  BUILTIN_MCPS[name] = { ...def, enabled: true }
}

function warnIfDebug(...args) {
  if (process.env.OMAGENTS_DEBUG === "1") {
    console.warn(...args)
  }
}

/**
 * Prepend the agent venv and skill script dirs to a PATH-like string.
 * Shared by the V1 `shell.env` hook and the V2 `shell "create.before"` hook.
 * Idempotent: entries already present are not duplicated.
 */
function buildPathWithAgentTools(currentPath) {
  const current = currentPath || process.env.PATH || ""
  const existing = current.split(path.delimiter)

  const parts = []
  if (!existing.includes(AGENT_VENV_BIN)) parts.push(AGENT_VENV_BIN)
  for (const dir of SKILL_SCRIPT_DIRS) {
    if (fs.existsSync(dir) && !existing.includes(dir)) {
      parts.push(dir)
    }
  }
  parts.push(current)

  return parts.join(path.delimiter)
}

// Extra context appended to compaction requests (V1 experimental.session
// .compacting / V2 session "compaction" hook) so the agent can resume work.
const COMPACTION_NOTE =
  "## OmAgents State Preservation\n" +
  "If you were processing a loop_engine task queue, run:\n" +
  "  loop_engine.py status <skill>\n" +
  "  loop_engine.py next <skill>\n" +
  "to resume where you left off.\n" +
  "If you had background tasks running, use parallel_status to check their state."

// Provisioning runs at most once per process, no matter how many times the
// host invokes the plugin entry point (V1 may call both the named export and
// default.server; V2 calls setup once).
let _provisioning = null

/**
 * Ensure the dedicated agent venv exists and has the required Python packages.
 * If Python 3 is not found, logs a clear warning with install instructions.
 * Never rejects.
 */
function ensurePythonDependencies(provisionBase = ensureBaseEnvironment) {
  if (_provisioning) return _provisioning
  _provisioning = (async () => {
    try {
      await provisionBase({
        logger: (message) => warnIfDebug(`[omagents] ${message}`),
      })
    } catch (error) {
      warnIfDebug(
        "[omagents] Python dependency check failed:",
        error.message,
        "\n  OmAgents requires Python 3.11+ for Python skills." +
          "\n  Install Python: https://www.python.org/downloads/" +
          "\n  After installing, restart OpenCode."
      )
    }
  })()
  return _provisioning
}

// ─── Load Superpowers (graceful degradation if unavailable) ──────────────────
//
// superpowers >= 6.4 ships a dual entry point: default export is
// { id, server, setup } where .server is the V1 plugin function and .setup is
// the V2 setup function. superpowers <= 6.3 exports the V1 plugin function
// directly. We resolve both halves once and let each host runtime pick its own.

let _superpowers = null // null = not tried, false = unavailable, { server, setup }

async function loadSuperpowers() {
  if (_superpowers !== null) return _superpowers
  if (!CORE_PATHS.superpowersDir) {
    _superpowers = false
    warnIfDebug(
      "[omagents] superpowers not available, skipping (install with: bun add superpowers)"
    )
    return null
  }
  try {
    const packageJson = JSON.parse(
      fs.readFileSync(path.join(CORE_PATHS.superpowersDir, "package.json"), "utf8")
    )
    const pluginEntry = path.join(CORE_PATHS.superpowersDir, packageJson.main || "index.js")
    const mod = await import(pathToFileURL(pluginEntry).href)
    const d = mod.default
    const server =
      typeof d === "function"
        ? d
        : typeof d?.server === "function"
          ? d.server
          : typeof mod.SuperpowersPlugin === "function"
            ? mod.SuperpowersPlugin
            : null
    const setup = typeof d?.setup === "function" ? d.setup : null
    _superpowers = server || setup ? { server, setup } : false
    if (!_superpowers) {
      warnIfDebug("[omagents] superpowers module found but no plugin export")
    }
  } catch {
    _superpowers = false // mark as tried-and-failed (distinct from null=not-tried)
    warnIfDebug(
      "[omagents] superpowers not available, skipping (install with: bun add superpowers)"
    )
  }
  return _superpowers || null
}

// ─── Plugin ──────────────────────────────────────────────────────────────────

export const OmagentsPlugin = async (ctx) => {
  // Inside the OmAgents source repo the published package yields to the
  // auto-discovered local checkout (see "Self-repo dedup guard" below).
  if (shouldYieldToLocalCheckout(ctx?.directory)) {
    return {}
  }

  // Load superpowers and run its V1 plugin function to get its hooks
  let superHooks = {}
  const sp = await loadSuperpowers()
  if (sp && sp.server) {
    try {
      superHooks = (await sp.server(ctx)) || {}
    } catch (err) {
      warnIfDebug("[omagents] superpowers plugin failed to initialize:", err.message)
    }
  }

  // Get parallel execution hooks
  const parallelHooks = createParallelHooks(ctx)

  // OmAgents config: register skills + MCPs
  const omagentsConfig = async (config) => {
    config.skills = config.skills || {}
    config.skills.paths = config.skills.paths || []
    if (!config.skills.paths.includes(SKILLS_DIR)) {
      config.skills.paths.push(SKILLS_DIR)
    }

    config.mcp = config.mcp || {}
    for (const [name, mcpConfig] of Object.entries(BUILTIN_MCPS)) {
      if (!config.mcp[name]) {
        config.mcp[name] = mcpConfig
      }
    }
  }

  // Merged config: superpowers first (register skills), then omagents, then parallel
  const mergedConfig = async (config) => {
    if (superHooks.config) await superHooks.config(config)
    await omagentsConfig(config)
    if (parallelHooks.config) await parallelHooks.config(config)
  }

  // V1 reads Superpowers skills directly from disk, so express the same
  // documentation-root override as the preference supported by those skills.
  const mergedSystemTransform = async (input, output) => {
    if (superHooks["experimental.chat.system.transform"]) {
      await superHooks["experimental.chat.system.transform"](input, output)
    }
    if (parallelHooks["experimental.chat.system.transform"]) {
      await parallelHooks["experimental.chat.system.transform"](input, output)
    }
    output.system = output.system || []
    if (!output.system.includes(SUPERPOWERS_DOCS_PATH_PREFERENCE)) {
      output.system.push(SUPERPOWERS_DOCS_PATH_PREFERENCE)
    }
  }

  // Merged messages.transform: superpowers bootstrap first, then Job Board
  const mergedMessagesTransform = async (input, output) => {
    if (superHooks["experimental.chat.messages.transform"]) {
      await superHooks["experimental.chat.messages.transform"](input, output)
    }
    if (parallelHooks["experimental.chat.messages.transform"]) {
      await parallelHooks["experimental.chat.messages.transform"](input, output)
    }
  }

  // Merged event: superpowers events first (if any), then parallel events
  const mergedEvent = async (input) => {
    if (superHooks.event) {
      await superHooks.event(input)
    }
    if (parallelHooks.event) {
      await parallelHooks.event(input)
    }
  }

  // Merged tool.execute.before
  const mergedToolBefore = async (input, output) => {
    if (superHooks["tool.execute.before"]) {
      await superHooks["tool.execute.before"](input, output)
    }
    if (parallelHooks["tool.execute.before"]) {
      await parallelHooks["tool.execute.before"](input, output)
    }
  }

  // Merged tool.execute.after
  const mergedToolAfter = async (input, output) => {
    if (superHooks["tool.execute.after"]) {
      await superHooks["tool.execute.after"](input, output)
    }
    if (parallelHooks["tool.execute.after"]) {
      await parallelHooks["tool.execute.after"](input, output)
    }
  }

  // Merge custom tools (superpowers tools + omagents tools)
  const mergedTools = {
    ...(superHooks.tool || {}),
    ...(parallelHooks.tool || {}),
  }

  return {
    config: mergedConfig,

    "session.created": async () => {
      if (superHooks["session.created"]) await superHooks["session.created"]()
      await ensurePythonDependencies()
    },

    "shell.env": async (input, output) => {
      // Run superpowers shell.env if present
      if (superHooks["shell.env"]) {
        await superHooks["shell.env"](input, output)
      }
      // Then prepend our venv + skill scripts to PATH (deduped: the host may
      // invoke this hook twice when both plugin entry points are picked up)
      output.env = output.env || {}
      output.env.PATH = buildPathWithAgentTools(output.env.PATH)
    },

    // Merged hooks
    "tool.execute.before": mergedToolBefore,
    "tool.execute.after": mergedToolAfter,
    "experimental.chat.messages.transform": mergedMessagesTransform,
    "experimental.chat.system.transform": mergedSystemTransform,
    "experimental.session.compacting": async (_input, output) => {
      output.context = output.context || []
      if (
        output.context.some(
          (c) => typeof c === "string" && c.includes("OmAgents State Preservation")
        )
      )
        return
      output.context.push(COMPACTION_NOTE)
    },
    event: mergedEvent,

    // Custom tools
    tool: mergedTools,
  }
}

// ─── OpenCode V2 ─────────────────────────────────────────────────────────────
//
// V2 (opencode 2.x) loads the default export's { id, setup } descriptor and
// never calls the V1 plugin function. setup() registers everything through
// the V2 plugin context: skills/MCP/commands/tools via domain transforms,
// shell env via ctx.shell.hook("create.before"), prompt context via
// ctx.session.hook("context"/"compaction"), and lifecycle via
// ctx.event.subscribe().

function collectSkillInfos() {
  const skills = []
  for (const definition of listSkillDefinitions({ host: "opencode-v2" })) {
    try {
      const rendered = renderSkillForHost(definition, "opencode-v2")
      skills.push({
        id: rendered.id,
        name: rendered.name,
        ...(rendered.description ? { description: rendered.description } : {}),
        path: rendered.path,
        content: rendered.body,
      })
    } catch (err) {
      warnIfDebug(`[omagents] failed to read skill "${definition.id}":`, err.message)
    }
  }
  return skills
}

// npx-based local MCP servers download their package on first run, which can
// exceed the host's default MCP startup timeout on a cold npx cache. Worse,
// a killed download never populates the cache, so every startup then fails
// identically. Give local servers a generous startup timeout (V2 shape).
const LOCAL_MCP_STARTUP_TIMEOUT_MS = 180_000

// Convert the V1-shaped built-in MCP definitions ({ type, command|url,
// enabled, ... }) to the V2 Mcp.ServerConfig shape (no `enabled` field).
function toV2McpConfig(def) {
  const { enabled, ...rest } = def
  if (def.type === "local" && !rest.timeout) {
    rest.timeout = { startup: LOCAL_MCP_STARTUP_TIMEOUT_MS }
  }
  return rest
}

// ─── Self-repo dedup guard ───────────────────────────────────────────────────
//
// When OpenCode runs inside the OmAgents source repo itself, the repo's own
// `.opencode/plugins/*.js` are auto-discovered as project plugins in addition
// to any globally-installed `@omagents/omagents` from the user's config. Both
// would register the same skills/MCPs/tools/hooks twice. The installed package
// detects this situation and yields, so the local checkout is the single
// active copy — which is also what a developer editing the working tree wants.

// True when this module is the published package (loaded from node_modules)
// rather than a source checkout.
const IS_INSTALLED_PACKAGE = (() => {
  const segments = __dirname.split(path.sep)
  for (let i = 0; i + 2 < segments.length; i++) {
    if (
      segments[i] === "node_modules" &&
      segments[i + 1] === "@omagents" &&
      segments[i + 2] === "omagents"
    ) {
      return true
    }
  }
  return false
})()

// True when `dir` is (or is inside) the OmAgents source repo, meaning its
// project-local `.opencode/plugins/index.js` will also be loaded by the host.
function isInsideOmagentsSourceRepo(dir) {
  let current = dir
  for (let depth = 0; depth < 10 && current; depth++) {
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(current, "package.json"), "utf8"))
      if (
        pkg.name === "@omagents/omagents" &&
        fs.existsSync(path.join(current, ".opencode", "plugins", "index.js")) &&
        path.resolve(current) !== path.resolve(OMAGENTS_DIR)
      ) {
        return true
      }
    } catch {
      // no readable package.json at this level — keep walking up
    }
    const parent = path.dirname(current)
    if (parent === current) break
    current = parent
  }
  return false
}

// The installed package yields when running inside the OmAgents source repo.
// All entry points funnel through here before registering anything.
function shouldYieldToLocalCheckout(projectDir) {
  return IS_INSTALLED_PACKAGE && !!projectDir && isInsideOmagentsSourceRepo(projectDir)
}

async function setupV2(ctx) {
  // V1 hosts may also invoke default.setup with a V1-shaped context (observed
  // on opencode 1.18.x). Detect it and return quietly — V1 is served entirely
  // by the server() entry point.
  if (
    !ctx ||
    typeof ctx.session?.hook !== "function" ||
    typeof ctx.skill?.transform !== "function" ||
    typeof ctx.tool?.transform !== "function"
  ) {
    return
  }

  // Inside the OmAgents source repo the published package yields to the
  // auto-discovered local checkout (see "Self-repo dedup guard" above).
  if (shouldYieldToLocalCheckout(ctx.location?.project?.directory || ctx.location?.directory)) {
    return
  }

  // Keep Superpowers' V2 bootstrap, but let Core be the single registration
  // path for every skill so host rendering also applies to Superpowers.
  const sp = await loadSuperpowers()
  if (sp && sp.setup) {
    try {
      await sp.setup({
        ...ctx,
        skill: {
          ...ctx.skill,
          transform: async () => {},
        },
      })
    } catch (err) {
      warnIfDebug("[omagents] superpowers v2 setup failed:", err.message)
    }
  }

  // Register all bundled skills as native V2 skills through Core rendering.
  try {
    const skills = collectSkillInfos()
    if (skills.length > 0) {
      await ctx.skill.transform((editor) => {
        for (const skill of skills) {
          // editor.add() decodes against the host Skill.Info schema and throws
          // on mismatch; contain per skill so one bad payload skips that skill
          // instead of disabling the whole plugin.
          try {
            editor.add(skill)
          } catch (err) {
            console.error(`[omagents] skill "${skill.id}" rejected by host, skipping:`, err)
          }
        }
      })
    }
  } catch (err) {
    console.error("[omagents] v2 skill registration failed:", err)
  }

  // Register built-in MCP servers (user config takes precedence)
  try {
    await ctx.mcp.transform((editor) => {
      for (const [name, def] of Object.entries(BUILTIN_MCPS)) {
        try {
          if (!editor.get(name)) {
            editor.set(name, toV2McpConfig(def))
          }
        } catch (err) {
          console.error(`[omagents] MCP server "${name}" rejected by host, skipping:`, err)
        }
      }
    })
  } catch (err) {
    console.error("[omagents] v2 MCP registration failed:", err)
  }

  // PATH injection for the agent venv + skill helper scripts
  try {
    await ctx.shell.hook("create.before", (event) => {
      try {
        event.env = event.env || {}
        event.env.PATH = buildPathWithAgentTools(event.env.PATH)
      } catch (err) {
        warnIfDebug("[omagents] v2 shell hook failed:", err.message)
      }
    })
  } catch (err) {
    console.error("[omagents] v2 shell hook registration failed:", err)
  }

  // State-preservation note on compaction requests
  try {
    await ctx.session.hook("compaction", (event) => {
      try {
        event.system = event.system || []
        if (
          event.system.some(
            (p) => p && typeof p.text === "string" && p.text.includes("OmAgents State Preservation")
          )
        )
          return
        event.system.push({ type: "text", text: COMPACTION_NOTE })
      } catch (err) {
        warnIfDebug("[omagents] v2 compaction hook failed:", err.message)
      }
    })
  } catch (err) {
    console.error("[omagents] v2 compaction hook registration failed:", err)
  }

  // Parallel execution engine (tools, hooks, /ps command, event subscription)
  let cleanupParallel
  try {
    cleanupParallel = await setupParallelV2(ctx)
  } catch (err) {
    console.error("[omagents] v2 parallel engine registration failed:", err)
  }

  // Provision the Python venv in the background (never blocks plugin load)
  void ensurePythonDependencies(ctx.omagents?.ensureBaseEnvironment)

  return async () => {
    try {
      await cleanupParallel?.()
    } catch {
      // best-effort
    }
  }
}

/**
 * Dual V1/V2 entry point.
 *
 * - V2 (opencode 2.x) reads `id` + `setup`.
 * - V1 (opencode 1.18.29+) calls `server()`.
 * - Older V1 releases scan named exports and call `OmagentsPlugin`.
 */
export default {
  id: "omagents",
  server: OmagentsPlugin,
  setup: setupV2,
}
